/**
 * Derives an owner's {@code identityKey}: the single value that duplicate detection compares. It is
 * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}, where the telephone is
 * E.164 (see {@link E164Telephone}), the email is lower-cased (empty when absent) and the household
 * id groups owners by last name and address (see {@link HouseholdId}). Two owners are duplicates
 * only when their whole keys are equal, so household members with different telephones differ here.
 */
public final class IdentityKey {

    private IdentityKey() {
    }

    public static String of(Owner owner) {
        String telephone = E164Telephone.toE164(owner.getTelephone());
        String email = owner.getEmail();
        String emailPart = (email == null || email.isBlank()) ? "" : email.toLowerCase(Locale.ROOT);
        return (telephone == null ? "" : telephone) + '|' + emailPart + '|' + HouseholdId.of(owner);
    }
}

